// DEV_RIO_001 — 案件入力（dry-run用サンプル。実運用では上流から差し込む）
// design/DATA_MODEL.md / ID_AND_IDEMPOTENCY_POLICY.md 準拠
const input = $input.first().json;
return [{ json: {
  idea: input.idea ?? 'Threads→note→Brain 計測1本目',
  source: input.source ?? 'owner',
  platform: input.platform ?? 'threads',
  est_revenue_30d: input.est_revenue_30d ?? 3980,
  effort_hours: input.effort_hours ?? 4,
  risk_level: input.risk_level ?? 'medium',
  compliance_flag: input.compliance_flag ?? 'OK',
  duplicate_of: input.duplicate_of ?? null,
  wip_revenue_experiments: input.wip_revenue_experiments ?? 1,
  wip_cap_revenue: 2
} }];

// 分類ロジック: EXECUTE_NOW / MERGE / VALIDATE / HOLD / STOP
// 基準: design/PORTFOLIO_INVENTORY.md §8 + WIP_POLICY.md
// ※ VALIDATE(不明) は EXECUTE_NOW より前に評価する（tests/classify_opportunity.test.mjs で検証済み）
const o = $input.first().json;
let classification, rationale;

if (o.compliance_flag && o.compliance_flag !== 'OK') {
  classification = 'STOP';
  rationale = 'compliance_flag が NG（規約/法令リスク）。offer_score 無効。';
} else if (o.duplicate_of) {
  classification = 'MERGE';
  rationale = `既存案件 ${o.duplicate_of} と重複。統合する。`;
} else if (o.wip_revenue_experiments >= o.wip_cap_revenue) {
  classification = 'HOLD';
  rationale = `収益実験WIPが上限(${o.wip_cap_revenue})に到達。先に既存を完了/停止する。`;
} else if (o.est_revenue_30d === null || o.risk_level === 'unknown') {
  classification = 'VALIDATE';
  rationale = '需要/収益性が未確定。小規模検証が必要（EXECUTE_NOW より優先）。';
} else if (o.est_revenue_30d >= 3000 && o.effort_hours <= 8 && o.risk_level !== 'high') {
  classification = 'EXECUTE_NOW';
  rationale = '30日期待収益が閾値以上・低工数・高リスクでない。計測付きで実行候補。';
} else {
  classification = 'HOLD';
  rationale = 'いずれの実行条件も満たさず、停止するほど負でもない。データ待ち。';
}

return [{ json: { ...o, classification, rationale } }];

// Job レコード生成（冪等性キー付き）: design/JOB_STATE_MACHINE.md / ID_AND_IDEMPOTENCY_POLICY.md
// ※ Date.now/新規UUIDは実行時に付与。ここでは決定的フォールバックも用意。
const o = $input.first().json;
const execId = $execution?.id ?? 'dryrun';
const ts = ($now ? $now.toISO() : new Date().toISOString());
const account_id = 'ai_store_lab';
const content_asset_id = 'intake-' + execId;
const action_type = 'opportunity_intake';
const idempotency_key = [account_id, o.platform, content_asset_id, action_type].join('|');

return [{ json: {
  job_id: 'job-' + execId,
  workflow: 'DEV_RIO_001_Opportunity_Intake',
  portfolio_id: 'port-rio',
  campaign_id: 'camp-store-ai',
  state: 'QUEUED',
  retry_count: 0,
  idempotency_key,
  classification: o.classification,
  rationale: o.rationale,
  idea: o.idea,
  est_revenue_30d: o.est_revenue_30d,
  owner_yes_no: 'PENDING',
  created_at: ts,
  updated_at: ts,
  note: 'dry-run。実運用では jobs テーブルへ append し、重複キーは再実行前チェックでスキップ。'
} }];
